    elements:Toggle("Auto Collect", section, setdata.collect, function(v)
        env.Collect = v
        env.setconfig("collect", v)
        if not env.Collect then return end
        while env.Collect do
            for i, v in pairs(plrPlot.Pads:GetChildren()) do
